function initMomentumCards(){document.querySelectorAll(".hover-momentum, .program-card, .tilt-card").forEach(e=>{e.addEventListener("mousemove",t=>{const o=e.getBoundingClientRect(),n=t.clientX-o.left,i=t.clientY-o.top,a=o.width/2,c=o.height/2,s=(i-c)/c*-10,r=(n-a)/a*10;gsap.to(e,{transformPerspective:1e3,rotateX:s,rotateY:r,scale:1.05,duration:.5,ease:"power2.out"})}),e.addEventListener("mouseleave",()=>{gsap.to(e,{rotateX:0,rotateY:0,scale:1,duration:.8,ease:"elastic.out(1, 0.5)"})})})}function initDirectionalHover(){document.querySelectorAll(".hover-directional li, .nav-link").forEach(e=>{e.addEventListener("mouseenter",t=>{const o=getDirection(t,e);animateDirection(e,"in",o)}),e.addEventListener("mouseleave",t=>{const o=getDirection(t,e);animateDirection(e,"out",o)})})}function getDirection(e,t){const o=t.offsetWidth,n=t.offsetHeight,i=t.getBoundingClientRect(),a=(e.pageX-i.left-o/2)*(o>n?n/o:1),c=(e.pageY-i.top-n/2)*(n>o?o/n:1);return Math.round((Math.atan2(c,a)*(180/Math.PI)+180)/90+3)%4}function animateDirection(e,t,o){const n=e.querySelector(".hover-content")||e;let i=0,a=0;switch(o){case 0:a=-100;break;case 1:i=100;break;case 2:a=100;break;case 3:i=-100}"in"===t?gsap.fromTo(n,{x:i+"%",y:a+"%",opacity:0},{x:"0%",y:"0%",opacity:1,duration:.4,ease:"power3.out"}):gsap.to(n,{x:i+"%",y:a+"%",opacity:0,duration:.4,ease:"power3.in"})}window.addEventListener("load",()=>{window.addEventListener("scroll",()=>{const e=window.scrollY,t=document.getElementById("header"),o=document.getElementById("scroll-progress");if(t&&(e>100?t.classList.add("navbar-scrolled"):t.classList.remove("navbar-scrolled")),o){const e=(document.body.scrollTop||document.documentElement.scrollTop)/(document.documentElement.scrollHeight-document.documentElement.clientHeight)*100;o.style.width=e+"%"}},{passive:!0});const e=document.getElementById("mobile-menu-btn"),t=document.getElementById("mobile-menu"),o=document.getElementById("close-menu-btn");e&&t&&e.addEventListener("click",e=>{e.stopPropagation(),t.classList.remove("hidden"),setTimeout(()=>{t.classList.remove("opacity-0");t.querySelectorAll(".mobile-nav-link").forEach((e,t)=>{setTimeout(()=>{e.classList.remove("translate-y-4","opacity-0")},50*t)})},10)}),o&&t&&o.addEventListener("click",()=>{t.classList.add("opacity-0");t.querySelectorAll(".mobile-nav-link").forEach(e=>{e.classList.add("translate-y-4","opacity-0")}),setTimeout(()=>{t.classList.add("hidden")},300)}),initMomentumCards(),initDirectionalHover()});